const rawId = $json.execution?.id;

if (typeof rawId !== 'string') {
  throw new Error('[Intake Resume error] execution.id must be a string.');
}

const normalizedId = rawId.trim();
if (!normalizedId || normalizedId.length > 4096) {
  throw new Error('[Intake Resume error] execution.id must be non-empty and at most 4096 characters.');
}

const primaryMessage = typeof $json.execution?.error?.message === 'string'
  ? $json.execution.error.message.trim()
  : '';
const secondaryMessage = typeof $json.execution?.error?.description === 'string'
  ? $json.execution.error.description.trim()
  : '';
const selectedMessage = primaryMessage || secondaryMessage || 'Unknown Intake Resume error';
const boundedMessage = selectedMessage.trim().slice(0, 2000);

return {
  json: {
    n8n_execution_id: normalizedId,
    error_message: boundedMessage,
  },
};

const normalized = $('Normalize Intake Error').first().json;
const rows = $input.all()
  .map(item => item.json ?? {})
  .filter(row => typeof row.id === 'string' && row.id.trim());

if (rows.length > 1) {
  throw new Error(`[Intake Resume error] Ownership invariant violation: updated ${rows.length} events.`);
}

const normalizedId = typeof normalized.n8n_execution_id === 'string'
  ? normalized.n8n_execution_id.trim()
  : '';
if (!normalizedId || normalizedId.length > 4096) {
  throw new Error('[Intake Resume error] Normalized execution identity is invalid.');
}

if (rows.length === 0) {
  return [{
    json: {
      event_updated: false,
      event_id: null,
      event_key: null,
      analysis_run_id: null,
      status: null,
      n8n_execution_id: normalizedId,
    },
  }];
}

const row = rows[0];
if (row.status !== 'failed') {
  throw new Error('[Intake Resume error] Updated event must have failed status.');
}

function boundedRequired(value, maxLength, fieldName) {
  if (typeof value !== 'string' || !value.trim()) {
    throw new Error(`[Intake Resume error] ${fieldName} is required.`);
  }
  return value.trim().slice(0, maxLength);
}

function boundedNullable(value, maxLength, fieldName) {
  if (value === null || value === undefined || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw new Error(`[Intake Resume error] ${fieldName} must be a string or null.`);
  }
  const normalizedValue = value.trim();
  return normalizedValue ? normalizedValue.slice(0, maxLength) : null;
}

return [{
  json: {
    event_updated: true,
    event_id: boundedRequired(row.id, 128, 'event_id'),
    event_key: boundedRequired(row.event_key, 512, 'event_key'),
    analysis_run_id: boundedNullable(row.analysis_run_id, 128, 'analysis_run_id'),
    status: 'failed',
    n8n_execution_id: normalizedId,
  },
}];
